import React, { useState, useEffect, useCallback } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { ChevronLeft, CheckCircle2, Clock, XCircle, Circle, RefreshCw, FileText, Send, Eye, Award, AlertTriangle } from 'lucide-react';
import { applicationApi } from '../../api/services';
import { PageLoader, Alert, Card, StatusBadge } from '../../components/common';
import { fmtDateTime, fmtCurrency, getLoanTypeLabel } from '../../utils/helpers';

// ── Status pipeline order ─────────────────────────────────────────────────────
const PIPELINE = [
  {
    status: 'DRAFT',
    label: 'Application Created',
    description: 'Your loan application has been created and saved as a draft.',
    icon: <FileText size={20} />,
    color: '#6b7280',
  },
  {
    status: 'SUBMITTED',
    label: 'Application Submitted',
    description: 'Your application has been submitted for review. Please upload all required documents.',
    icon: <Send size={20} />,
    color: '#3b82f6',
  },
  {
    status: 'DOCS_PENDING',
    label: 'Documents Pending',
    description: 'Our team is waiting for your supporting documents. Please upload them promptly.',
    icon: <Clock size={20} />,
    color: '#f59e0b',
  },
  {
    status: 'DOCS_VERIFIED',
    label: 'Documents Verified',
    description: 'All your documents have been verified successfully. Your application is queued for review.',
    icon: <CheckCircle2 size={20} />,
    color: '#10b981',
  },
  {
    status: 'UNDER_REVIEW',
    label: 'Under Review',
    description: 'A loan officer is reviewing your application. This usually takes 2–5 business days.',
    icon: <Eye size={20} />,
    color: '#8b5cf6',
  },
  {
    status: 'APPROVED',
    label: 'Approved',
    description: 'Congratulations! Your loan application has been approved.',
    icon: <Award size={20} />,
    color: '#10b981',
  },
  {
    status: 'REJECTED',
    label: 'Rejected',
    description: 'Your application could not be approved at this time. Please check admin remarks.',
    icon: <XCircle size={20} />,
    color: '#ef4444',
  },
  {
    status: 'CLOSED',
    label: 'Closed',
    description: 'This application has been closed.',
    icon: <Circle size={20} />,
    color: '#9ca3af',
  },
];

const TERMINAL = ['APPROVED', 'REJECTED', 'CLOSED'];
const REJECTION_STATUSES = ['REJECTED'];

function getStepState(pipelineStatus, currentStatus, history) {
  const wasReached = history.some(h => h.toStatus === pipelineStatus);
  if (currentStatus === pipelineStatus) return 'current';
  if (wasReached) return 'done';
  if (REJECTION_STATUSES.includes(currentStatus) && !wasReached) return 'skipped';
  return 'upcoming';
}

function StepIcon({ state, icon, color }) {
  if (state === 'done') return (
    <div style={{ width: 44, height: 44, borderRadius: '50%', background: '#10b981', display: 'flex', alignItems: 'center', justifyContent: 'center', color: '#fff', flexShrink: 0 }}>
      <CheckCircle2 size={22} />
    </div>
  );
  if (state === 'current') return (
    <div style={{ width: 44, height: 44, borderRadius: '50%', background: color, display: 'flex', alignItems: 'center', justifyContent: 'center', color: '#fff', flexShrink: 0, boxShadow: `0 0 0 4px ${color}30` }}>
      {icon}
    </div>
  );
  if (state === 'skipped') return (
    <div style={{ width: 44, height: 44, borderRadius: '50%', background: '#f3f4f6', border: '2px solid #e5e7eb', display: 'flex', alignItems: 'center', justifyContent: 'center', color: '#d1d5db', flexShrink: 0 }}>
      {icon}
    </div>
  );
  return (
    <div style={{ width: 44, height: 44, borderRadius: '50%', background: '#f9fafb', border: '2px dashed #e5e7eb', display: 'flex', alignItems: 'center', justifyContent: 'center', color: '#d1d5db', flexShrink: 0 }}>
      {icon}
    </div>
  );
}

function TimelineStep({ step, state, historyEntry, isLast }) {
  return (
    <div style={{ display: 'flex', gap: '1rem', position: 'relative' }}>
      {/* connector line */}
      {!isLast && (
        <div style={{
          position: 'absolute', left: 21, top: 44, width: 2, height: 'calc(100% + 1.25rem)',
          background: state === 'done' ? '#10b981' : '#e5e7eb',
          transition: 'background 0.3s',
        }} />
      )}

      <StepIcon state={state} icon={step.icon} color={step.color} />

      <div style={{ flex: 1, paddingBottom: isLast ? 0 : '1.75rem' }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: '0.625rem', flexWrap: 'wrap' }}>
          <span style={{
            fontWeight: 600, fontSize: '0.9375rem',
            color: state === 'upcoming' || state === 'skipped' ? 'var(--navy-400)' : 'var(--navy-900)',
          }}>
            {step.label}
          </span>
          {state === 'current' && (
            <span style={{ fontSize: '0.6875rem', fontWeight: 700, letterSpacing: '0.05em', background: step.color + '20', color: step.color, padding: '2px 8px', borderRadius: 999 }}>
              CURRENT
            </span>
          )}
        </div>

        <p style={{ fontSize: '0.8125rem', color: state === 'upcoming' || state === 'skipped' ? 'var(--navy-300)' : 'var(--navy-500)', margin: '2px 0 0', lineHeight: 1.5 }}>
          {step.description}
        </p>

        {historyEntry && (
          <div style={{ marginTop: '0.5rem', fontSize: '0.75rem', color: 'var(--navy-400)', display: 'flex', flexWrap: 'wrap', gap: '0.75rem' }}>
            <span>🕐 {fmtDateTime(historyEntry.changedAt)}</span>
            <span>• Changed by: {historyEntry.changedBy}</span>
            {historyEntry.remarks && historyEntry.toStatus !== 'DRAFT' && (
              <span style={{ color: 'var(--navy-500)', fontStyle: 'italic' }}>"{historyEntry.remarks}"</span>
            )}
          </div>
        )}
      </div>
    </div>
  );
}

export default function ApplicationStatusPage() {
  const { id } = useParams();
  const navigate = useNavigate();

  const [app, setApp]         = useState(null);
  const [history, setHistory] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError]     = useState('');
  const [refreshing, setRefreshing] = useState(false);

  const load = useCallback(async (silent = false) => {
    if (!silent) setLoading(true);
    else setRefreshing(true);
    try {
      const [appRes, histRes] = await Promise.all([
        applicationApi.getById(id),
        applicationApi.getStatusHistory(id),
      ]);
      setApp(appRes.data);
      setHistory(histRes.data || []);
    } catch {
      setError('Failed to load application status.');
    } finally {
      setLoading(false);
      setRefreshing(false);
    }
  }, [id]);

  useEffect(() => { load(); }, [load]);

  if (loading) return <PageLoader />;
  if (!app) return <Alert type="error">Application not found.</Alert>;

  const currentStatus = app.status;
  const isTerminal    = TERMINAL.includes(currentStatus);

  // Build visible pipeline (hide CLOSED unless that's the actual status)
  const visiblePipeline = PIPELINE.filter(p =>
    p.status !== 'CLOSED' || currentStatus === 'CLOSED'
  );

  // For REJECTED, drop APPROVED from pipeline display
  const displayPipeline = currentStatus === 'REJECTED'
    ? visiblePipeline.filter(p => p.status !== 'APPROVED')
    : visiblePipeline.filter(p => p.status !== 'REJECTED');

  const progressPipeline = currentStatus === 'REJECTED' || currentStatus === 'CLOSED'
    ? visiblePipeline.filter(p => p.status !== 'APPROVED')
    : visiblePipeline.filter(p => p.status !== 'REJECTED' && p.status !== 'CLOSED');

  const totalSteps   = progressPipeline.length;
  const currentIndex = progressPipeline.findIndex(p => p.status === currentStatus);
  const progressPct  = isTerminal
    ? 100
    : Math.max(0, Math.round(((currentIndex) / (totalSteps - 1)) * 100));

  const statusColor = currentStatus === 'APPROVED' ? '#10b981'
    : currentStatus === 'REJECTED' ? '#ef4444'
    : '#3b82f6';

  return (
    <div style={{ maxWidth: 700 }}>
      {/* Header */}
      <div style={{ display: 'flex', alignItems: 'center', gap: '1rem', marginBottom: '1.5rem', flexWrap: 'wrap' }}>
        <button className="btn btn-ghost btn-sm" onClick={() => navigate(`/applications/${id}`)} style={{ padding: '6px 8px' }}>
          <ChevronLeft size={16} />
        </button>
        <div style={{ flex: 1 }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: '0.75rem', flexWrap: 'wrap' }}>
            <h2>Track Application #{id}</h2>
            <StatusBadge status={currentStatus} />
          </div>
          <div style={{ fontSize: '0.8125rem', color: 'var(--navy-500)', marginTop: 2 }}>
            {getLoanTypeLabel(app.loanType)} · {fmtCurrency(app.loanAmount)}
          </div>
        </div>
        <button className="btn btn-secondary btn-sm" onClick={() => load(true)} disabled={refreshing}>
          <RefreshCw size={13} style={{ animation: refreshing ? 'spin 1s linear infinite' : 'none' }} /> Refresh
        </button>
      </div>

      {error && <Alert type="error" style={{ marginBottom: '1rem' }}>{error}</Alert>}

      {/* Progress bar card */}
      <Card style={{ padding: '1.5rem', marginBottom: '1.25rem' }}>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-end', marginBottom: '0.75rem' }}>
          <div>
            <div style={{ fontSize: '0.75rem', fontWeight: 600, letterSpacing: '0.06em', color: 'var(--navy-400)', textTransform: 'uppercase', marginBottom: 2 }}>Application Progress</div>
            <div style={{ fontSize: '1.5rem', fontWeight: 700, color: statusColor }}>
              {isTerminal ? '100' : progressPct}%
            </div>
          </div>
          <div style={{ textAlign: 'right' }}>
            <div style={{ fontSize: '0.75rem', color: 'var(--navy-400)' }}>Current Stage</div>
            <div style={{ fontWeight: 600, color: 'var(--navy-800)' }}>
              {PIPELINE.find(p => p.status === currentStatus)?.label}
            </div>
          </div>
        </div>

        <div style={{ height: 10, borderRadius: 999, background: '#f3f4f6', overflow: 'hidden' }}>
          <div style={{
            height: '100%', borderRadius: 999,
            width: `${isTerminal ? 100 : progressPct}%`,
            background: statusColor,
            transition: 'width 0.6s ease',
          }} />
        </div>

        {!isTerminal && (
          <p style={{ fontSize: '0.8125rem', color: 'var(--navy-500)', marginTop: '0.75rem' }}>
            Estimated completion: {currentStatus === 'UNDER_REVIEW' ? '2–5 business days' : '1–3 business days'}
          </p>
        )}
        {currentStatus === 'APPROVED' && (
          <div style={{ marginTop: '0.75rem', padding: '0.75rem 1rem', background: '#f0fdf4', borderRadius: 'var(--radius-lg)', border: '1px solid #bbf7d0', color: '#166534', fontSize: '0.875rem', fontWeight: 500 }}>
            🎉 Congratulations! Your loan has been approved. Our team will contact you with next steps.
          </div>
        )}
        {currentStatus === 'REJECTED' && app.remarks && (
          <div style={{ marginTop: '0.75rem', padding: '0.75rem 1rem', background: '#fef2f2', borderRadius: 'var(--radius-lg)', border: '1px solid #fecaca', fontSize: '0.875rem' }}>
            <div style={{ fontWeight: 600, color: '#991b1b', marginBottom: 2 }}>Rejection Reason:</div>
            <div style={{ color: '#7f1d1d' }}>{app.remarks}</div>
          </div>
        )}
      </Card>

      {/* Timeline card */}
      <Card style={{ padding: '1.5rem' }}>
        <div style={{ fontWeight: 600, fontSize: '1rem', marginBottom: '1.5rem', display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
          <Clock size={16} style={{ color: 'var(--teal-600)' }} /> Status Timeline
        </div>

        {displayPipeline.map((step, idx) => {
          const state = getStepState(step.status, currentStatus, history);
          const historyEntry = history.find(h => h.toStatus === step.status);
          return (
            <TimelineStep
              key={step.status}
              step={step}
              state={state}
              historyEntry={historyEntry}
              isLast={idx === displayPipeline.length - 1}
            />
          );
        })}
      </Card>

      {/* Raw history log */}
      {history.length > 0 && (
        <Card style={{ padding: '1.25rem', marginTop: '1.25rem' }}>
          <div style={{ fontWeight: 600, fontSize: '0.9375rem', marginBottom: '0.875rem' }}>Full Change Log</div>
          <div style={{ display: 'flex', flexDirection: 'column', gap: '0.5rem' }}>
            {[...history].reverse().map((h, i) => (
              <div key={i} style={{ display: 'flex', gap: '0.75rem', fontSize: '0.8125rem', alignItems: 'flex-start', padding: '0.5rem 0', borderBottom: i < history.length - 1 ? '1px solid var(--navy-100)' : 'none' }}>
                <span style={{ color: 'var(--navy-400)', flexShrink: 0, minWidth: 150 }}>{fmtDateTime(h.changedAt)}</span>
                <span style={{ color: 'var(--navy-600)' }}>
                  {h.fromStatus ? <><StatusBadge status={h.fromStatus} /> → </> : ''}
                  <StatusBadge status={h.toStatus} />
                </span>
                <span style={{ color: 'var(--navy-400)', fontStyle: 'italic' }}>{h.remarks}</span>
              </div>
            ))}
          </div>
        </Card>
      )}

      {history.length === 0 && !loading && (
        <Card style={{ padding: '1.5rem', marginTop: '1.25rem', textAlign: 'center', color: 'var(--navy-400)' }}>
          <AlertTriangle size={28} style={{ marginBottom: '0.5rem', opacity: 0.4 }} />
          <div style={{ fontSize: '0.875rem' }}>No status history yet. History is recorded as your application progresses.</div>
        </Card>
      )}
    </div>
  );
}
